#!/usr/bin/env bash

input=/home/eval/data/paths.txt
output=/home/eval/data/parts.txt

while IFS= read -r path; do
  dir=${path%/*}
  base=${path##*/}
  stem=$base
  ext=

  if [[ $base == ?*.* ]]; then
    ext=${base##*.}
    stem=${base%.*}
  fi

  printf '%s|%s|%s|%s\n' "$dir" "$base" "$stem" "$ext"
done < "$input" > "$output"

exit 0

